// 1. Merge düğümünden gelen tüm karışık verileri al
const gelenVeriler = $input.all();

// Depoları hazırla
let temizEtkinlikListesi = {};
let havaDurumuVerisi = null;

gelenVeriler.forEach(item => {
  const veri = item.json;

  // --- A) HAVA DURUMU KONTROLÜ ---
  // OpenWeatherMap verisi genellikle 'list' ve 'city' içerir
  if (veri.list && veri.city) {
    havaDurumuVerisi = {
        sehir: veri.city.name,
        tahminler: veri.list.slice(0, 8) // Sadece önümüzdeki 24 saati al (8 x 3 saat)
    };
  }

  // --- B) TAKVİM ETKİNLİĞİ KONTROLÜ ---
  // Google (summary) veya Outlook (subject)
  else if (veri.summary || veri.subject) {

      const baslik = veri.summary || veri.subject || "İsimsiz";
      // Tarih formatlarını yakala
      let hamZaman = veri.start?.dateTime || veri.start?.date || veri.start;

      if (hamZaman) {
        // Dakikasına kadar alıp anahtar yap (Tekilleştirme için)
        // "2025-12-08T16:30:00.0000" -> "2025-12-08T16:30"
        const zamanAnahtari = (typeof hamZaman === 'string') ? hamZaman.substring(0, 16) : "Bilinmiyor";

        if (!temizEtkinlikListesi[zamanAnahtari]) {
          temizEtkinlikListesi[zamanAnahtari] = {
            baslik: baslik,
            zaman: hamZaman,
            kaynak: veri.htmlLink ? "Google" : (veri.webLink ? "Outlook" : "Diğer"),
            // Online toplantı mı diye ipucu ekleyelim
            detay: veri.description || veri.bodyPreview || "",
            lokasyon: veri.location?.displayName || veri.location || ""
          };
        } else {
          // Çakışma varsa kaynağı güncelle
          if (!temizEtkinlikListesi[zamanAnahtari].kaynak.includes(veri.htmlLink ? "Google" : "Outlook")) {
             temizEtkinlikListesi[zamanAnahtari].kaynak += " & Diğer";
          }
        }
      }
  }
});

// 3. Hepsini tek paket yapıp Gemini'ye gönder
return [
  {
    json: {
      takvim: Object.values(temizEtkinlikListesi),
      hava_durumu: havaDurumuVerisi || "Hava durumu verisi çekilemedi."
    }
  }
];

// 1. Gemini'nin karmaşık çıktısının içindeki "text" kısmını buluyoruz
const root = $input.item.json;
let rawText = "";

if (root.content && root.content.parts && root.content.parts[0]) {
   rawText = root.content.parts[0].text;
} else if (root.text) {
   rawText = root.text;
} else if (root.output) {
   rawText = root.output;
}

// 2. Markdown işaretlerini (```json ve ```) temizliyoruz
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

try {
  // 3. Temiz metni gerçek JSON objesine çeviriyoruz
  const jsonData = JSON.parse(cleanText);
  return jsonData;
} catch (e) {
  // Hata olursa varsayılan olarak "sohbet" moduna atalım
  return { intent: "general_chat", error: "JSON okunamadı" };
}

// 1. Danışman Gemini'den gelen metni güvenli bir şekilde alıyoruz.
// (Düğüm isminin 'Google Gemini Chat' olduğunu varsayıyorum, değilse parantez içini düzelt)
// En garantisi: $input.all() kullanmaktır.

const gelenVeri = $input.first().json;

// Gemini'nin cevabını buluyoruz (text veya content.parts[0].text)
let cevapMetni = "";

if (gelenVeri.content && gelenVeri.content.parts) {
    cevapMetni = gelenVeri.content.parts[0].text;
} else if (gelenVeri.text) {
    cevapMetni = gelenVeri.text;
} else if (gelenVeri.output) {
    cevapMetni = gelenVeri.output;
}

// 2. Temiz bir JSON olarak paketleyip döndürüyoruz
return {
    cevap: cevapMetni,
    tip: "oneri",
    rota: "null"
};

// 1. Düğüm ismine bakmadan, direkt önceki adımdan gelen veriyi alıyoruz.
// "Referenced node doesn't exist" hatası burada çözülüyor.
const gelenVeri = $input.first().json;

// 2. Gemini'den gelen 'date_reference' bilgisini al (Yoksa 'today' varsay)
const referans = gelenVeri.date_reference || "today"; 

// 3. Şu anki zamanı al
const simdi = new Date();
let baslangic = new Date(simdi);
let bitis = new Date(simdi);

// 4. Referansa göre tarihleri ayarla
if (referans.includes("tomorrow") || referans.includes("yarın")) {
    // YARIN
    baslangic.setDate(simdi.getDate() + 1);
    baslangic.setHours(0,0,0,0);

    bitis.setDate(simdi.getDate() + 1);
    bitis.setHours(23,59,59,999);

} else if (referans.includes("week") || referans.includes("hafta")) {
    // BU HAFTA
    baslangic.setHours(0,0,0,0);
    bitis.setDate(simdi.getDate() + 7);
    bitis.setHours(23,59,59,999);

} else {
    // BUGÜN (Varsayılan)
    baslangic.setHours(0,0,0,0);
    bitis.setHours(23,59,59,999);
}

// 5. Tarihleri ISO formatına çevirip döndür
return {
    start_date: baslangic.toISOString(),
    end_date: bitis.toISOString(),
    referans: referans
};

// 1. Supabase'den gelen veriyi al
let history = $input.all();

// 2. GARANTİ SIRALAMA: Tarihe göre (En yeniden -> Eskiye)
try {
    history.sort((a, b) => {
        const dateA = new Date(a.json.created_at || new Date());
        const dateB = new Date(b.json.created_at || new Date());
        return dateB - dateA;
    });
} catch (e) {
    // Tarih formatı bozuksa sıralamayı pas geç
}

// 3. Sadece son 6 mesajı al
history = history.slice(0, 6);

// 4. Sohbet akışına uygun olsun diye ters çevir (Eskiden -> Yeniye)
history.reverse();

let contextText = "";

if (history.length === 0) {
    contextText = "Henüz bir konuşma geçmişi yok.";
} else {
    history.forEach(item => {
        const chat = item.json;
        const roleName = chat.role === 'user' ? "KULLANICI" : "ASİSTAN";
        const mesajIcerigi = chat.message || "";
        contextText += `${roleName}: ${mesajIcerigi}\n`;
    });
}

// --- 5. HATA DÜZELTME KISMI (GÜVENLİ ERİŞİM) --- 🛡️

let webhookBody = {};

// 'try-catch' ile Webhook verisini güvenli bir şekilde çekmeye çalışıyoruz
try {
    // Düğüm adın "Webhook" ise burası çalışır. Değilse hata vermez, boş geçer.
    // Eğer Webhook düğümünün adı farklıysa (Örn: "Webhook Trigger") parantez içini değiştir!
    if ($('Webhook') && $('Webhook').first()) {
        webhookBody = $('Webhook').first().json.body || {};
    }
} catch (error) {
    console.log("Webhook verisi okunamadı, varsayılanlar kullanılacak.");
}

// Artık 'webhookBody' boş olsa bile kod patlamaz
const yeniSoru = webhookBody.text || webhookBody.soru || "Soru yok";
const userId = webhookBody.user_id || "test_user"; 

return {
    gecmis_baglam: contextText,
    yeni_soru: yeniSoru,
    user_id: userId 
};

// 1. Gemini'den gelen ham veriyi al
// (Eğer düğüm adı 'Gemini Chat' değilse, $input.all() kullanabilirsin)
const geminiData = $input.first().json;

// 2. Metni güvenli bir şekilde çıkar
let cevapMetni = "";

if (geminiData.content && geminiData.content.parts && geminiData.content.parts[0]) {
    cevapMetni = geminiData.content.parts[0].text;
} else if (geminiData.text) {
    cevapMetni = geminiData.text; // Bazen model text olarak dönebilir
} else {
    cevapMetni = "Bir hata oluştu, cevap okunamadı.";
}

// 3. Standart Formatta Döndür
return {
    "cevap": cevapMetni,
    "tip": "bot_mesaji", // Flutter'da buna göre ikon gösterebilirsin (Örn: Takvim ikonu)
    "rota": "null",
};

// 1. Gemini'den gelen metni al
// (Gemini bazen ```json ... ``` etiketiyle gönderir, onları temizliyoruz)
const geminiRawText = $input.first().json.content.parts[0].text;
const temizJsonString = geminiRawText.replace(/```json|```/g, '').trim();

// 2. Metni Gerçek JSON Objesine Çevir
let navigasyonVerisi = {};
try {
    navigasyonVerisi = JSON.parse(temizJsonString);
} catch (e) {
    // Gemini saçmalarsa varsayılan değer
    navigasyonVerisi = { 
        "cevap": "İstediğin sayfayı tam anlayamadım, ana sayfaya dönelim.", 
        "rota": "/home" 
    };
}

// 3. Flutter İçin Standart Paketi Hazırla
return {
    "cevap": navigasyonVerisi.cevap,
    "tip": "navigasyon",  // Bu sabit kalmalı, Flutter bunu kontrol ediyor
    "rota": navigasyonVerisi.rota // Burası artık DİNAMİK! (/settings, /profile vs.)
};

// 1. Önceki Gemini adımından gelen tarih referansını al
// (Webhook -> Gemini -> Switch -> Bu Düğüm)
// $input.first() yerine direkt kökten (Gemini Intent) verisini almak daha güvenlidir.
// Eğer Gemini düğümünün adı "Niyet Analizi" ise: $('Niyet Analizi').first().json...
// Ama biz genel $json üzerinden gidelim:
const gelenVeri = $input.first().json; 
const referans = gelenVeri.date_reference || "today"; // Varsayılan: Bugün

// 2. Tarih Hesaplama
const simdi = new Date();
let baslangic = new Date(simdi);
let bitis = new Date(simdi);

// Saatleri sıfırla (Günün başlangıcı ve sonu)
baslangic.setHours(0,0,0,0);
bitis.setHours(23,59,59,999);

let cevapMetni = "Bugünkü maillerini kontrol ediyorum...";

if (referans.includes("yesterday") || referans.includes("dün")) {
    // DÜN
    baslangic.setDate(simdi.getDate() - 1);
    bitis.setDate(simdi.getDate() - 1);
    cevapMetni = "Dünkü maillerini getiriyorum...";
} 
else if (referans.includes("tomorrow") || referans.includes("yarın")) {
    // YARIN (Mail için mantıksız ama takvim için olabilir, yine de kalsın)
    baslangic.setDate(simdi.getDate() + 1);
    bitis.setDate(simdi.getDate() + 1);
    cevapMetni = "Yarınki planlara bakıyorum...";
}
else if (referans.includes("week") || referans.includes("hafta")) {
    // BU HAFTA (Son 7 gün)
    baslangic.setDate(simdi.getDate() - 7);
    cevapMetni = "Son bir haftadaki maillerine bakıyorum...";
}

// 3. FLUTTER İÇİN ÇIKTI PAKETİ
return {
    "cevap": cevapMetni,      // Asistan bunu sesli söyleyecek
    "tip": "mailleri_ozetle", // Flutter bu komutu görünce harekete geçecek!
    "filtre": {
        // Flutter'ın DateTime.parse() ile okuyacağı ISO formatlar
        "baslangic_tarihi": baslangic.toISOString(), 
        "bitis_tarihi": bitis.toISOString(),
        "referans": referans
    }
};

// Gelen karmaşık veriyi al
const body = $input.item.json.body;
const komut = body.kullanici_komutu || "Özet geç";
const mailler = body.emails || []; // Senin gönderdiğin liste 'emails' içinde

// AI için basitleştirilmiş liste hazırla
const temizListe = mailler.map(mail => {
    const data = mail.data || {};

    // Konu (Summary) bulma
    let konu = data.summary || "Konu Yok";
    if (data.cevap && data.cevap.length > 0) konu = data.cevap[0].baslik;

    // Özet Metni (Voice Script) bulma - En önemli kısım burası!
    let ozet = data.voice_script || data.sesli_okuma || "İçerik yok.";

    return {
        konu: konu,
        ozet: ozet
    };
});

// Çıktı olarak sadece komutu ve temiz listeyi veriyoruz
return {
    json: {
        temiz_komut: komut,
        temiz_veriler: JSON.stringify(temizListe) // String olarak gönderiyoruz ki Prompt içine tam otursun
    }
};

// 1. Gemini'den gelen ham metni bul
const root = $input.item.json;
let rawText = "";

// Gemini'nin farklı çıktı formatlarına karşı önlem
if (root.content && root.content.parts && root.content.parts[0]) {
    rawText = root.content.parts[0].text;
} else if (root.text) {
    rawText = root.text;
} else if (root.output) {
    rawText = root.output;
} else {
    // Veri yoksa hata dönmemesi için
    return { json: { okunacak_metin: "Maalesef şu an cevap oluşturulamadı." } };
}

// 2. Markdown (```json) temizliği yap
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. JSON'a çevir ve gönder
try {
    const parsedData = JSON.parse(cleanText);

    // Eğer başarılıysa temiz JSON dön
    return { json: parsedData };

} catch (e) {
    // Eğer AI bozuk JSON ürettiyse, metni olduğu gibi düz yazı olarak gönder
    // Böylece Flutter hata vermez, en azından metni okur.
    return { 
        json: { 
            okunacak_metin: cleanText 
        } 
    };
}
